verifyPaymentScript:
// Read-only sandbox payment verification. Never trusts webhook payment fields.
function "connector/stripe/verify_supplier_payment" {
  input {
    int supplier_checkout_intent_id
  }
  stack {
    precondition ($input.supplier_checkout_intent_id > 0) {
      error_type = "inputerror"
      error = "A supplier checkout intent is required"
    }
    db.get supplier_checkout_intents {
      field_name = "id"
      field_value = $input.supplier_checkout_intent_id
    } as $intent
    precondition ($intent != null) {
      error_type = "notfound"
      error = "Supplier checkout intent not found"
    }
    precondition ($intent.provider_slug == "nuitee" && $intent.environment == "sandbox" && $intent.currency == "EUR" && $intent.selling_price > 0) {
      error_type = "inputerror"
      error = "Only EUR Nuitée sandbox checkout intents are allowed"
    }
    db.get orders {
      field_name = "id"
      field_value = $intent.order_id
    } as $order
    precondition ($order != null) {
      error_type = "notfound"
      error = "Order not found"
    }
    precondition ($intent.stripe_checkout_session_id != null && $intent.stripe_checkout_session_id != "" && $order.stripe_checkout_session_id == $intent.stripe_checkout_session_id && $order.currency == "EUR" && $order.total_amount == $intent.selling_price) {
      error_type = "inputerror"
      error = "Order and supplier checkout do not match"
    }
    var $expected_amount {
      value = (($intent.selling_price * 100)|round:0|to_int)
    }
    api.request {
      url = "https://api.stripe.com/v1/checkout/sessions/" ~ ($intent.stripe_checkout_session_id|url_encode)
      method = "GET"
      params = {}
      headers = ["Authorization: Bearer " ~ ($env.STRIPE_SECRET_KEY_test|to_text)]
    } as $session_response
    precondition ($session_response.response.status == 200) {
      error_type = "inputerror"
      error = "Unable to verify Stripe checkout session"
    }
    var $session {
      value = $session_response.response.result
    }
    precondition ($session.object == "checkout.session" && $session.id == $intent.stripe_checkout_session_id && $session.livemode == false && $session.mode == "payment" && $session.status == "complete" && $session.payment_status == "paid" && $session.currency == "eur" && $session.amount_total == $expected_amount) {
      error_type = "inputerror"
      error = "Stripe has not confirmed an exact sandbox payment"
    }
    precondition (($session.metadata.supplier_order_id|to_text) == ($order.id|to_text) && ($session.metadata.supplier_checkout_intent_id|to_text) == ($intent.id|to_text) && $session.metadata.supplier_fulfillment == "nuitee" && $session.metadata.supplier_flow == "step4_sandbox_v1" && $session.payment_intent != null && $session.payment_intent != "") {
      error_type = "inputerror"
      error = "Stripe checkout metadata does not match this supplier order"
    }
    precondition ($intent.stripe_payment_intent_id == null || $intent.stripe_payment_intent_id == "" || $intent.stripe_payment_intent_id == $session.payment_intent) {
      error_type = "inputerror"
      error = "Payment intent has changed"
    }
    api.request {
      url = "https://api.stripe.com/v1/payment_intents/" ~ ($session.payment_intent|url_encode) ~ "?expand[]=latest_charge.balance_transaction"
      method = "GET"
      params = {}
      headers = ["Authorization: Bearer " ~ ($env.STRIPE_SECRET_KEY_test|to_text)]
    } as $payment_response
    precondition ($payment_response.response.status == 200) {
      error_type = "inputerror"
      error = "Unable to verify Stripe payment intent"
    }
    var $payment {
      value = $payment_response.response.result
    }
    precondition ($payment.object == "payment_intent" && $payment.id == $session.payment_intent && $payment.livemode == false && $payment.status == "succeeded" && $payment.currency == "eur" && $payment.amount == $expected_amount && $payment.amount_received == $expected_amount) {
      error_type = "inputerror"
      error = "Payment is incomplete or does not match the order amount"
    }
    precondition ($payment.latest_charge.object == "charge" && $payment.latest_charge.paid == true && $payment.latest_charge.livemode == false && $payment.latest_charge.payment_intent == $payment.id && $payment.latest_charge.amount == $expected_amount && $payment.latest_charge.currency == "eur" && $payment.latest_charge.refunded == false && $payment.latest_charge.amount_refunded == 0 && $payment.latest_charge.disputed == false) {
      error_type = "inputerror"
      error = "Payment charge is missing, refunded or disputed"
    }
  }
  response = {
    verified: true
    environment: "sandbox"
    order_id: $order.id
    supplier_checkout_intent_id: $intent.id
    stripe_checkout_session_id: $session.id
    stripe_payment_intent_id: $payment.id
    amount_minor: $expected_amount
    currency: "EUR"
    voucher_allowed: false
  }
}

claimPaymentScript:
// Claims a verified sandbox payment once. Unknown/processing attempts are never automatically retried.
function "connector/nuitee/claim_paid_checkout" {
  input {
    int supplier_checkout_intent_id
  }
  stack {
    function.run "connector/stripe/verify_supplier_payment" {
      input = {supplier_checkout_intent_id: $input.supplier_checkout_intent_id}
    } as $payment
    precondition ($payment.verified == true && $payment.environment == "sandbox") {
      error_type = "inputerror"
      error = "Verified sandbox payment required"
    }
    var $claimed { value = false }
    var $claim_status { value = "blocked" }
    db.transaction {
      stack {
        db.get supplier_checkout_intents {
          field_name = "id"
          field_value = $input.supplier_checkout_intent_id
          lock = true
        } as $locked_intent
        precondition ($locked_intent != null && $locked_intent.environment == "sandbox" && $locked_intent.provider_slug == "nuitee" && $locked_intent.order_id == $payment.order_id && $locked_intent.stripe_checkout_session_id == $payment.stripe_checkout_session_id && $locked_intent.currency == $payment.currency && (($locked_intent.selling_price * 100)|round:0|to_int) == $payment.amount_minor) {
          error_type = "inputerror"
          error = "Checkout changed during payment verification"
        }
        precondition ($locked_intent.stripe_payment_intent_id == null || $locked_intent.stripe_payment_intent_id == "" || $locked_intent.stripe_payment_intent_id == $payment.stripe_payment_intent_id) {
          error_type = "inputerror"
          error = "Payment binding changed"
        }
        var.update $claim_status { value = $locked_intent.status }
        conditional {
          if ($locked_intent.status == "pending_payment" && ($locked_intent.booking_attempts ?? 0) == 0) {
            precondition ($locked_intent.prebook_id != null && $locked_intent.prebook_id != "" && $locked_intent.client_reference != null && $locked_intent.client_reference != "") {
              error_type = "inputerror"
              error = "Prebook and stable booking reference required"
            }
            db.edit supplier_checkout_intents {
              field_name = "id"
              field_value = $locked_intent.id
              data = {
                status: "processing"
                stripe_payment_intent_id: $payment.stripe_payment_intent_id
                booking_attempts: 1
                last_error: null
                updated_at: now
              }
            } as $processing_intent
            var.update $claimed { value = true }
            var.update $claim_status { value = "processing" }
          }
        }
      }
    }
  }
  response = {
    claimed: $claimed
    status: $claim_status
    environment: "sandbox"
    order_id: $payment.order_id
    supplier_checkout_intent_id: $input.supplier_checkout_intent_id
    stripe_payment_intent_id: $payment.stripe_payment_intent_id
    voucher_allowed: false
  }
}

prepareCheckoutScript:
// Internal sandbox prebook guard. Preserves the approved sale price; does not create a payment or booking.
function "supplier/checkout/prepare" {
  input {
    int deal_id
    text checkin filters=trim
    text checkout filters=trim
    int guests
  }

  stack {
    db.get deals {
      field_name = "id"
      field_value = $input.deal_id
    } as $before_deal

    db.query supplier_deals {
      where = $db.supplier_deals.deal_id == $input.deal_id
      return = {type: "single"}
    } as $before_supplier

    function.run "supplier/availability/check" {
      input = {
        deal_id : $input.deal_id
        checkin : $input.checkin
        checkout: $input.checkout
        guests  : $input.guests
      }
    } as $availability

    precondition ($availability.available && $availability.environment == "sandbox") {
      error_type = "inputerror"
      error = "No approved, margin-safe sandbox offer is available"
    }

    function.run "connector/adapters/nuitee/prebook" {
      input = {offer_id: $availability.offer_id}
    } as $prebook

    db.get deals {
      field_name = "id"
      field_value = $input.deal_id
    } as $deal

    db.query supplier_deals {
      where = $db.supplier_deals.deal_id == $input.deal_id
      return = {type: "single"}
    } as $supplier

    api.lambda {
      code = """
        const a=$var.availability, p=$var.prebook, d=$var.deal, s=$var.supplier;
        const fail=(code,message)=>({ready:false,can_pay:false,environment:'sandbox',code,message});
        const canonical=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
        if(!d||!s||d.status!=='active'||!d.approved_at||d.deleted_at||s.provider!=='nuitee'||s.environment!=='sandbox')return fail('NOT_APPROVED','Deal is niet meer goedgekeurd.');
        if(canonical(d)!==canonical($var.before_deal)||canonical(s)!==canonical($var.before_supplier)||Number(d.price)!==a.customer_price)return fail('DEAL_CHANGED','Deal is gewijzigd tijdens de controle.');
        if(Date.now()>a.valid_until)return fail('EXPIRED','Beschikbaarheidscontrole is verlopen.');
        if(!p?.success||!p.data?.prebookId)return fail('PREBOOK_FAILED','Nuitee heeft de prijs niet bevestigd.');
        const q=p.data;
        if(q.currency!=='EUR'||typeof q.price!=='number'||!Number.isFinite(q.price)||q.price<=0)return fail('INVALID_PRICE','Definitieve leveranciersprijs ontbreekt.');
        const rooms=q.roomTypes;
        if(!Array.isArray(rooms)||rooms.length!==1||!Array.isArray(rooms[0].rates)||rooms[0].rates.length!==1)return fail('INVALID_ROOM','Definitieve kamervoorwaarden zijn onvolledig.');
        const r=rooms[0].rates[0], approved=(s.supplier_mapping||s.supplier_content)?.offer, old=approved?.rates?.[0];
        if(!old||r.name!==old.name||r.boardType!==old.boardType||r.boardName!==old.boardName||r.adultCount!==old.adultCount||r.childCount!==old.childCount||r.remarks!==old.remarks||canonical(r.cancellationPolicies)!==canonical(old.cancellationPolicies))return fail('CONDITIONS_CHANGED','Kamer of annuleringsvoorwaarden zijn gewijzigd.');
        const fees=r.retailRate?.taxesAndFees;
        if(!Array.isArray(fees)||fees.some(t=>typeof t.included!=='boolean'||t.currency!=='EUR'||typeof t.amount!=='number'||!Number.isFinite(t.amount)||t.amount<0))return fail('INVALID_FEES','Definitieve lokale kosten zijn onvolledig.');
        const local=fees.filter(t=>!t.included).map(t=>({description:t.description,amount:t.amount,currency:t.currency,pay_at_property:true}));
        const sorted=v=>canonical(v.slice().sort((x,y)=>canonical(x).localeCompare(canonical(y))));
        if(sorted(local)!==sorted(a.local_fees))return fail('LOCAL_FEES_CHANGED','Lokale kosten zijn gewijzigd sinds goedkeuring.');
        const cfg=s.pricing_config;
        if(!cfg||['processing_fee','stripe_fee_percentage','stripe_fee_fixed','min_margin_amount'].some(k=>typeof cfg[k]!=='number'||!Number.isFinite(cfg[k])||cfg[k]<0)||cfg.stripe_fee_percentage>=100)return fail('INVALID_CONFIG','Kostenconfiguratie ontbreekt.');
        const sale=Math.round(d.price*100),cost=Math.ceil(q.price*100-1e-8),processing=Math.ceil(Math.max(cfg.processing_fee,1.30)*100-1e-8),stripe=Math.ceil(sale*cfg.stripe_fee_percentage/100+cfg.stripe_fee_fixed*100-1e-8),margin=sale-cost-processing-stripe;
        if(margin<Math.ceil(cfg.min_margin_amount*100-1e-8))return fail('MARGIN_BLOCKED','Definitieve inkoopprijs past niet binnen de goedgekeurde verkoopprijs.');
        return {ready:true,can_pay:false,environment:'sandbox',deal_id:d.id,supplier_deal_id:s.id,approval_fingerprint:canonical({deal:d,supplier:s}),prebook_id:q.prebookId,checkin:$input.checkin,checkout:$input.checkout,guests:$input.guests,currency:'EUR',selling_price:sale/100,supplier_amount:cost/100,processing_reserve:processing/100,stripe_reserve:stripe/100,margin_after_reserve:margin/100,local_fees:local,cancellation_policies:r.cancellationPolicies,checked_at:Date.now(),message:'Sandboxprijs bevestigd; betaalroute nog niet aangesloten.'};
        """
      timeout = 5
    } as $result
  }

  response = $result
}

createSessionScript:
// Internal sandbox only. Creates an immutable checkout snapshot and an idempotent Stripe test session.
function "supplier/checkout/create_sandbox_session" {
 input {
  int deal_id
  text checkin filters=trim
  text checkout filters=trim
  int guest_count
  int customer_id
  text request_key filters=trim
  json holder
  json guests
 }
 stack {
  api.lambda {
   code = """
const i=$input;
if(!/^[a-zA-Z0-9_-]{12,64}$/.test(i.request_key))throw new Error('Use a stable 12-64 character request key');
if(!i.holder||!i.holder.firstName||!i.holder.lastName||!/^.+@.+\..+$/.test(i.holder.email||''))throw new Error('Holder name and email are required');
if(!Array.isArray(i.guests)||i.guests.length!==i.guest_count||i.guests.some(g=>!g.firstName||!g.lastName||g.occupancyNumber!==1||!/^.+@.+\..+$/.test(g.email||'')))throw new Error('Name and email are required for every guest in room 1');
return {reference:'SD-SBX-'+i.customer_id+'-'+i.request_key,request:{deal_id:i.deal_id,checkin:i.checkin,checkout:i.checkout,guest_count:i.guest_count,customer_id:i.customer_id,holder:i.holder,guests:i.guests}};
"""
   timeout = 5
  } as $validated
precondition ($validated.reference != null && $validated.request.customer_id == $input.customer_id) {error_type="inputerror"
error="Invalid checkout input"}
  db.query supplier_checkout_intents {
   where = $db.supplier_checkout_intents.client_reference == $validated.reference
   return = {type:"single"}
  } as $existing
  var $quote { value = null }
  conditional {
   if ($existing == null) {
    function.run "supplier/checkout/prepare" {
     input = {deal_id:$input.deal_id,checkin:$input.checkin,checkout:$input.checkout,guests:$input.guest_count}
    } as $prepared
    precondition ($prepared.ready == true && $prepared.environment == "sandbox") {
     error_type = "inputerror"
     error = "Approved sandbox quote required"
    }
    var.update $quote { value = $prepared }
   }
  }
  var $intent { value = null }
  db.transaction {
   stack {
    db.get customers {
     field_name = "id"
     field_value = $input.customer_id
     lock = true
    } as $customer
    precondition ($customer != null && $customer.email == $input.holder.email) {
     error_type = "inputerror"
     error = "Existing test customer must match holder email"
    }
    db.query supplier_checkout_intents {
     where = $db.supplier_checkout_intents.client_reference == $validated.reference
     return = {type:"single"}
    } as $prior
    conditional {
     if ($prior != null) {
      api.lambda {
       code = """
const canonical=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
const p=$var.prior;
return {valid:p.environment==='sandbox'&&p.provider_slug==='nuitee'&&canonical(p.checkout_context?.request)===canonical($var.validated.request)};
"""
       timeout = 5
      } as $same_request
precondition ($same_request.valid == true) {error_type="inputerror"
error="Request key already used with different checkout details"}
      var.update $intent { value = $prior }
     }
     else {
      db.get deals {
       field_name = "id"
       field_value = $input.deal_id
       lock = true
      } as $locked_deal
      db.get supplier_deals {
       field_name = "id"
       field_value = $quote.supplier_deal_id
       lock = true
      } as $locked_supplier
      api.lambda {
       code = """
const q=$var.quote,d=$var.locked_deal,s=$var.locked_supplier;
const canonical=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
if(!q||!q.ready||q.environment!=='sandbox'||Date.now()-q.checked_at>60000||q.approval_fingerprint!==canonical({deal:d,supplier:s}))throw new Error('Quote expired or approved deal changed');
return {schema_version:1,flow:'nuitee-step4-sandbox',request:$var.validated.request,quote:q,product_name:'SeasonDeals sandbox - '+d.title};
"""
       timeout = 5
      } as $context
precondition ($context.flow == "nuitee-step4-sandbox") {error_type="inputerror"
error="Quote expired or approved deal changed"}
      db.add orders {
       data = {deal_id:$input.deal_id,customer_id:$input.customer_id,total_amount:$quote.selling_price,status:"pending_payment",currency:"EUR",guests:$input.guest_count,updated_at:now}
      } as $new_order
      db.add supplier_checkout_intents {
       data = {
        created_at:now,updated_at:now,order_id:$new_order.id,provider_slug:"nuitee",environment:"sandbox",prebook_id:$quote.prebook_id,client_reference:$validated.reference,holder:$input.holder,guests:$input.guests,currency:"EUR",supplier_amount:$quote.supplier_amount,selling_price:$quote.selling_price,processing_fee:$quote.processing_reserve,stripe_fee_estimated:$quote.stripe_reserve,margin_estimate_pre_payment:$quote.margin_after_reserve,payment_method_type:"unknown",status:"creating_checkout",booking_attempts:0,checkout_context:$context
       }
      } as $new_intent
      var.update $intent { value = $new_intent }
     }
    }
   }
  }
  conditional {
   if ($intent.stripe_checkout_session_id == null || $intent.stripe_checkout_session_id == "") {
    precondition ($intent.status == "creating_checkout") {
     error_type = "inputerror"
     error = "Checkout state does not permit payment creation"
    }
    api.request {
     url = "https://api.stripe.com/v1/checkout/sessions"
     method = "POST"
     params = {
      success_url:"https://seasondeals.nl/",cancel_url:"https://seasondeals.nl/",mode:"payment",adaptive_pricing:{enabled:"false"},customer_email:$intent.holder.email,payment_method_types:["card","ideal"],
      line_items:[{price_data:{currency:"eur",product_data:{name:$intent.checkout_context.product_name},unit_amount:(($intent.selling_price * 100)|round:0|to_int)},quantity:1}],
      metadata:{supplier_order_id:$intent.order_id,supplier_checkout_intent_id:$intent.id,supplier_fulfillment:"nuitee",supplier_flow:"step4_sandbox_v1"}
     }
     headers = ["Authorization: Bearer " ~ ($env.STRIPE_SECRET_KEY_test|to_text),"Content-Type: application/x-www-form-urlencoded","Idempotency-Key: sd-sandbox-checkout-" ~ ($intent.id|to_text)]
    } as $stripe
    precondition ($stripe.response.status == 200 && $stripe.response.result.object == "checkout.session" && $stripe.response.result.livemode == false && $stripe.response.result.currency == "eur" && $stripe.response.result.amount_total == (($intent.selling_price * 100)|round:0|to_int)) {
     error_type = "inputerror"
     error = "Stripe test session not confirmed; retry only with the same request key"
    }
    api.lambda {
     code = """
return {...$var.intent.checkout_context,checkout_url:$var.stripe.response.result.url};
"""
     timeout = 5
    } as $stored_context
    db.transaction {
     stack {
      db.get supplier_checkout_intents {
field_name="id"
field_value=$intent.id
lock=true
} as $locked_intent
      precondition ($locked_intent.stripe_checkout_session_id == null || $locked_intent.stripe_checkout_session_id == "" || $locked_intent.stripe_checkout_session_id == $stripe.response.result.id) {error="Checkout session binding changed"}
      db.edit orders {
       field_name="id"
       field_value=$intent.order_id
       data={stripe_checkout_session_id:$stripe.response.result.id,updated_at:now}
      } as $session_order
      conditional {
       if ($locked_intent.status == "creating_checkout") {
        db.edit supplier_checkout_intents {
         field_name="id"
         field_value=$intent.id
         data={stripe_checkout_session_id:$stripe.response.result.id,checkout_context:$stored_context,status:"pending_payment",updated_at:now}
        } as $session_intent
        var.update $intent {value=$session_intent}
       }
       else {var.update $intent {value=$locked_intent}}
      }
     }
    }
   }
  }
 }
 response={environment:"sandbox",order_id:$intent.order_id,supplier_checkout_intent_id:$intent.id,status:$intent.status,checkout_url:$intent.checkout_context.checkout_url,selling_price:$intent.selling_price,currency:"EUR",voucher_allowed:false}
}

fulfillScript:
// Internal sandbox fulfillment. A verified payment is claimed once; uncertain attempts never rebook automatically.
function "supplier/checkout/fulfill_sandbox_payment" {
 input { int supplier_checkout_intent_id }
 stack {
  function.run "connector/nuitee/claim_paid_checkout" {input={supplier_checkout_intent_id:$input.supplier_checkout_intent_id}} as $claim
  db.get supplier_checkout_intents {field_name="id"
field_value=$input.supplier_checkout_intent_id} as $intent
  conditional {
   if ($claim.claimed != true) {
    db.query supplier_bookings {where=$db.supplier_bookings.order_id == $claim.order_id && $db.supplier_bookings.environment == "sandbox" && $db.supplier_bookings.booking_status == "confirmed"
return={type:"single"}} as $existing_booking
    return {value={claimed:false,idempotent_replay:true,status:$intent.status,order_id:$claim.order_id,supplier_booking_id:$existing_booking.id,voucher_allowed:($intent.status == "booked" && $existing_booking != null)}}
   }
  }
  db.edit orders {field_name="id"
field_value=$claim.order_id
data={status:"paid",payment_status:"paid",paid_at:now,updated_at:now}} as $paid_order
  var $fresh {value=null}
  try_catch {
   try {
    function.run "supplier/checkout/prepare" {input={deal_id:$intent.checkout_context.request.deal_id,checkin:$intent.checkout_context.request.checkin,checkout:$intent.checkout_context.request.checkout,guests:$intent.checkout_context.request.guest_count}} as $prepared
    var.update $fresh {value=$prepared}
   }
   catch {var.update $fresh {value={ready:false}}}
  }
  api.lambda {
   code="""
const q=$var.fresh,i=$var.intent,old=i.checkout_context?.quote;
const canonical=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
return {valid:!!q?.ready&&q.environment==='sandbox'&&q.currency==='EUR'&&q.selling_price===i.selling_price&&q.approval_fingerprint===old?.approval_fingerprint&&canonical(q.local_fees)===canonical(old?.local_fees)&&canonical(q.cancellation_policies)===canonical(old?.cancellation_policies)};
"""
   timeout=5
  } as $safe_quote
  conditional {
   if ($safe_quote.valid != true) {
    db.edit supplier_checkout_intents {field_name="id"
field_value=$intent.id
data={status:"manual_attention",last_error:"Paid, but approved offer could not be safely revalidated. No booking submitted.",processed_at:now,updated_at:now}} as $blocked
    db.edit orders {field_name="id"
field_value=$intent.order_id
data={provider_sync_status:"error",provider_sync_error:"Offer changed after payment; review/refund required. No booking submitted.",updated_at:now}} as $blocked_order
